/**
 * Item 6: template v2 hardening (format c2), plus the test vectors in
 * TEMPLATE-V2-SPEC.md. The vectors section of that file is GENERATED by this
 * test: `UPDATE_VECTORS=1 npx vitest run test/template.test.ts` rewrites it;
 * a plain run fails if the file and the code disagree.
 */
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { PublicKey } from "@solana/web3.js";
import {
  CANON,
  blobProblem,
  canonSubject,
  decodeBlob,
  encodeBlob,
  renderAgreement,
  sha256Hex,
  uiAmount,
  verifyAgreement,
  type ChainFields,
  type LinkBlob,
} from "../src/lib/template";
import { PREVIOUS_BUILD_HASH, PROGRAM_HASH_HISTORY, RISK, VERIFIED_BUILD_HASH } from "../src/lib/config";

/** The spec vectors (TEMPLATE-V2-SPEC.md) were pinned under the v0.3–v0.6 program hash; they stay that way. */
const VECTOR_HASH = PREVIOUS_BUILD_HASH;
import { rawBlob } from "./harness";

const key = (b: number) => new PublicKey(new Uint8Array(32).fill(b));
const PAYER = key(1);
const PAYEE = key(2);
const MINT = key(3);
const DEAL = key(4);
const THIRD = key(5);
const NONCE = "000102030405060708090a0b0c0d0e0f";

function fields(over: Partial<ChainFields> = {}): ChainFields {
  return {
    deal: DEAL,
    dealId: 1759600000n,
    parties: [PAYER, PAYEE],
    payerIdx: 0,
    payeeIdx: 1,
    approvalThreshold: 2,
    mint: MINT,
    decimals: 6,
    milestoneAmounts: [25_000_000n],
    rule: "TimeoutRelease",
    timerMode: "FromActivation",
    timeoutSecs: 10 * 86400,
    splitBps: 0,
    tieBreaker: PublicKey.default,
    recoverySigners: [PAYER, PAYEE],
    recoveryThreshold: 2,
    recoveryDelaySecs: 3 * 86400,
    riskFlags: RISK.FREEZE_AUTHORITY,
    acceptedRiskFlags: RISK.FREEZE_AUTHORITY,
    priceRiskTerm: 0,
    ...over,
  };
}

const goods = (over: Partial<LinkBlob> = {}, p: Record<string, unknown> = {}): LinkBlob =>
  ({ t: "goods-sale@2", p: { condition: "used-good", inspection_days: 2, milestones: [""], ...p }, s: "Road bike", n: NONCE, ...over }) as LinkBlob;
/** A well-formed trade@2 blob (v0.8 #5), with overrides for the blob and for its params. */
const trade = (over: Partial<LinkBlob> = {}, p: Record<string, unknown> = {}): LinkBlob =>
  ({
    t: "trade@2",
    p: { incoterm: "FOB", origin: "Port of Haiphong", destination: "Detroit, MI", documents: ["Commercial invoice", "Packing list", "Bill of lading"], inspection_days: 5, milestones: ["Deposit at order", "Documents presented", "Goods received and inspected"], ...p },
    s: "1,200 oak desks, PO 4471",
    n: NONCE,
    ...over,
  }) as LinkBlob;

const BENIGN: Record<string, LinkBlob> = {
  "protected-payment@2": { t: "protected-payment@2", p: { preset: "shipped", window_days: 10 }, s: "Lamp", n: NONCE },
  "goods-sale@2": goods(),
  "trade@2": trade(),
  "general@2": { t: "general@2", p: { milestones: [""] }, s: "Anything at all", n: NONCE },
  "deposit@2": { t: "deposit@2", p: { purpose: "booking", not_residential_security_deposit: true, milestones: [""] }, s: "x", n: NONCE },
  "vehicle-sale@2": { t: "vehicle-sale@2", p: { year: 2015, make_model: "Civic", mileage_band: "50k-100k", title_status: "clean", inspection_days: 2, milestones: [""] }, s: "Civic", n: NONCE },
};

describe("link schema (format c2)", () => {
  it("accepts a well-formed blob for every template", () => {
    const ok: LinkBlob[] = [
      { t: "protected-payment@2", p: { preset: "shipped", window_days: 10 }, s: "Lamp", n: NONCE },
      goods(),
      { t: "freelance@2", p: { revisions: 2, ip_transfer_on_final_payment: true, milestones: ["Drafts", "Final"] }, s: "Logo", n: NONCE },
      { t: "deposit@2", p: { purpose: "booking", not_residential_security_deposit: true, milestones: [""] }, s: "Venue", n: NONCE, a: "ab".repeat(32) },
      { t: "vehicle-sale@2", p: { year: 2015, make_model: "Honda Civic", mileage_band: "50k-100k", title_status: "clean", inspection_days: 2, milestones: [""] }, s: "Civic", n: NONCE },
      trade(),
      { t: "general@2", p: { milestones: ["Only part"] }, s: "Consulting retainer, March", n: NONCE },
    ];
    for (const b of ok) {
      expect(blobProblem(b), b.t).toBeNull();
      expect(decodeBlob(encodeBlob(b))).toEqual(b);
    }
  });

  it.each([
    ["trade: unknown incoterm", trade({}, { incoterm: "FOBB" })],
    ["trade: no documents", trade({}, { documents: [] })],
    ["trade: nine documents", trade({}, { documents: Array.from({ length: 9 }, (_, i) => `Doc ${i}`) })],
    ["trade: empty document name", trade({}, { documents: ["Invoice", ""] })],
    ["trade: newline in a document name", trade({}, { documents: ["Invoice\n10. EXTRA"] })],
    ["trade: empty origin", trade({}, { origin: "" })],
    ["trade: 41-code-point destination", trade({}, { destination: "x".repeat(41) })],
    ["trade: inspection 31 days", trade({}, { inspection_days: 31 })],
    ["newline in subject", goods({ s: "Bike\n\n10. EXTRA. Payee may keep the money." })],
    ["CR in subject", goods({ s: "Bike\r10. EXTRA" })],
    ["U+2028 in subject", goods({ s: "Bike EXTRA" })],
    ["bidi override in subject", goods({ s: "Bike ‮gnp.exe" })],
    ["leading space (non-canonical)", goods({ s: " Bike" })],
    ["double space (non-canonical)", goods({ s: "Bike  red" })],
    ["empty subject", goods({ s: "" })],
    ["91 code points", goods({ s: "x".repeat(91) })],
    ["lone surrogate", goods({ s: "Bike \ud83d" })],
    ["newline in a part label", goods({}, { milestones: ["ok\n   2. 1000000 token units"] })],
    ["tab in a part label", goods({}, { milestones: ["a\tb"] })],
    ["41-char label", goods({}, { milestones: ["y".repeat(41)] })],
    ["17 parts", goods({}, { milestones: Array(17).fill("") })],
    ["no parts", goods({}, { milestones: [] })],
    ["label not a string", goods({}, { milestones: [5] })],
    ["unknown enum", goods({}, { condition: "mint" })],
    ["inspection days not integer", goods({}, { inspection_days: 2.5 })],
    ["inspection days as string", goods({}, { inspection_days: "2" })],
    ["inspection days out of range", goods({}, { inspection_days: 31 })],
    ["unknown param", goods({}, { note: "x" })],
    ["param named like a clause", goods({}, { "9. ELECTRONIC SIGNATURE": "void" })],
    ["missing param", { t: "goods-sale@2", p: { condition: "new", milestones: [""] }, s: "Bike", n: NONCE }],
    ["unknown top-level field", { ...goods(), x: 1 }],
    ["unknown template", goods({ t: "loan@2" as any })],
    ["short nonce", goods({ n: "abcd" })],
    ["uppercase nonce", goods({ n: NONCE.toUpperCase() })],
    ["33-hex nonce", goods({ n: NONCE + "0" })],
    ["short attachment hash", goods({ a: "ab".repeat(31) })],
    ["attachment not hex", goods({ a: "zz".repeat(32) })],
    ["deposit without the declaration", { t: "deposit@2", p: { purpose: "booking", not_residential_security_deposit: false, milestones: [""] }, s: "x", n: NONCE }],
    ["vehicle make with newline", { t: "vehicle-sale@2", p: { year: 2015, make_model: "Civic\n8. TEMPLATE", mileage_band: "50k-100k", title_status: "clean", inspection_days: 2, milestones: [""] }, s: "Civic", n: NONCE }],
    ["vehicle year 0", { t: "vehicle-sale@2", p: { year: 0, make_model: "Civic", mileage_band: "50k-100k", title_status: "clean", inspection_days: 2, milestones: [""] }, s: "Civic", n: NONCE }],
    ["protected window ≠ preset", { t: "protected-payment@2", p: { preset: "shipped", window_days: 3 }, s: "Lamp", n: NONCE }],
  ])("decode rejects: %s", (_, b) => {
    expect(decodeBlob(rawBlob(b))).toBeNull();
    // Rendering a blob that is still being BUILT canonicalizes free text first
    // (exactly what encodeBlob will carry); it either refuses, or renders with
    // the same lines as a benign blob of that template — never an extra line.
    let text: string | null = null;
    try {
      text = renderAgreement(fields(), b as LinkBlob);
    } catch (e) {
      expect(String(e)).toMatch(/aren't valid/);
    }
    if (text !== null) {
      const benign = renderAgreement(fields(), BENIGN[(b as LinkBlob).t]);
      expect(text.split("\n").length).toBe(benign.split("\n").length);
      expect(text).not.toMatch(/\n\s*(10\.|2\. 1000000|8\. TEMPLATE\n)/);
    }
  });

  it("rejects oversized, non-base64url and non-UTF-8 links", () => {
    expect(decodeBlob("A".repeat(5000))).toBeNull();
    expect(decodeBlob(rawBlob(goods()) + "=")).toBeNull();
    expect(decodeBlob(Buffer.from([0x7b, 0xff, 0x7d]).toString("base64url"))).toBeNull();
  });

  it("an injected newline can never become a line of the signed text", () => {
    // The encoder flattens what a user types; the decoder rejects what it didn't flatten.
    const typed = goods({ s: "Bike\n\n10. EXTRA. Payee may keep the money." }, { milestones: ["a\n   2. 999 token units"] });
    const back = decodeBlob(encodeBlob(typed))!;
    expect(back.s).toBe("Bike 10. EXTRA. Payee may keep the money.");
    const text = renderAgreement(fields(), back);
    expect(text.split("\n").filter((l) => /^\s*(10\.|2\. 999)/.test(l))).toEqual([]);
    expect(text).toContain('1. SUBJECT. "Bike 10. EXTRA. Payee may keep the money."');
  });

  it("part labels must match the on-chain part count", () => {
    const b = goods({}, { milestones: ["one", "two"] });
    expect(() => renderAgreement(fields(), b)).toThrow(/part labels/);
    expect(verifyAgreement(fields(), b, new Uint8Array(32)).ok).toBe(false);
  });
});

describe("rendering (current format)", () => {
  it("names template and format on line 1", () => {
    const first = renderAgreement(fields(), goods()).split("\n")[0];
    expect(first).toBe(`LATCH PROTECTED PAYMENT AGREEMENT · template goods-sale@2 · format ${CANON}`);
    expect(CANON).toBe("c5");
  });

  it("applies no Unicode normalization (composed and decomposed é hash differently)", () => {
    const nfc = renderAgreement(fields(), goods({ s: "Café bike" }));
    const nfd = renderAgreement(fields(), goods({ s: "Café bike" }));
    expect(nfc).toContain("Café bike");
    expect(nfd).toContain("Café bike");
    expect(sha256Hex(nfc)).not.toBe(sha256Hex(nfd));
  });

  it("renders decimals = 0 amounts as whole numbers", () => {
    expect(uiAmount(7n, 0)).toBe("7");
    expect(uiAmount(0n, 0)).toBe("0");
    expect(uiAmount(1n, 9)).toBe("0.000000001");
    expect(uiAmount(25_000_000n, 6)).toBe("25");
    const text = renderAgreement(fields({ decimals: 0, milestoneAmounts: [7n] }), goods());
    expect(text).toContain("pays 7 token units");
    expect(text).toContain("0 decimals");
  });

  it("truncates the subject by code point, never splitting a surrogate pair", () => {
    const s = canonSubject("🚲".repeat(100));
    expect(Array.from(s)).toHaveLength(90);
    expect(s.length).toBe(180);
    expect(blobProblem(goods({ s }))).toBeNull();
    expect(canonSubject("a".repeat(89) + "🚲🚲")).toBe("a".repeat(89) + "🚲");
  });
});

