function hexBytes(s: string) {
  return Array.from(new TextEncoder().encode(s)).length;
}

function vectorsFor(format: "c5" | "c3", hash: string, heading: string, intro: string, vectors: Vector[] = VECTORS): string[] {
  const out: string[] = [`### ${heading}`, "", intro, ""];
  for (const v of vectors) {
    const text = renderAgreement(v.f, v.blob, hash, format);
    const f = v.f;
    out.push(`#### ${v.title}`, "", v.note, "", "```");
    out.push(`deal              ${f.deal.toBase58()}`);
    out.push(`dealId            ${f.dealId}`);
    out.push(`parties           [payer 0x01×32, payee 0x02×32]  approvals ${f.approvalThreshold}`);
    out.push(`mint / decimals   0x03×32 / ${f.decimals}`);
    out.push(`milestoneAmounts  [${f.milestoneAmounts.join(", ")}]`);
    out.push(`rule / timer      ${f.rule} / ${f.timerMode}, timeout ${f.timeoutSecs}`);
    out.push(`recovery          ${f.recoveryThreshold}-of-${f.recoverySigners.length}, delay ${f.recoveryDelaySecs}`);
    out.push(`risk / accepted   ${f.riskFlags} / ${f.acceptedRiskFlags}, priceRiskTerm ${f.priceRiskTerm}`);
    out.push(`link blob (JCS)   ${JSON.stringify(decodeBlob(encodeBlob(v.blob)))}`);
    out.push(`link (base64url)  ${encodeBlob(v.blob)}`);
    out.push("```", "");
    out.push(`Expected: **${hexBytes(text)} bytes**, SHA-256`, `\`${sha256Hex(text)}\`.`, "");
    out.push("Full canonical text (between the fence lines; every line ends with LF, including the last):", "", "````", text.replace(/\n$/, ""), "````", "");
  }
  return out;
}

/** §8: the current format first (c5 under the deployed build), then the frozen c3 set every earlier client signed under. */
function vectorsMarkdown(): string {
  return [
    ...vectorsFor("c5", VERIFIED_BUILD_HASH, `Format c5 under the deployed build \`${VERIFIED_BUILD_HASH}\` (current)`,
      "What the app renders today: section 5 states the dispute policy and the payee's refund right, and the limit never resets.", [...VECTORS, TRADE_VECTOR, GENERAL_VECTOR]),
    ...vectorsFor("c3", VECTOR_HASH, `Historical: format c3 under \`${VECTOR_HASH}\``,
      "Texts signed by v0.3–v0.6 clients. Still verified by `PROGRAM_HASH_HISTORY`; digests are pinned by hand in `test/template.test.ts` and never regenerated."),
  ].join("\n");
}

